return {["fb10_01"]={["BgmDown"]=1,["dsc"]=[[这里四周描金漆银，装扮得富丽堂皇，别有气派，门廊下挂着丝雀画眉，叫声婉转动听，几株名贵的珊瑚就放在院中，四下散放着一些躺椅，以供在院中休息。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_01]],["name"]=[[何园后院]],["permission"]=2,["role1"]=[[fb10r01_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_02]],["visible"]=1},["fb10_02"]={["BgmDown"]=1,["down"]=[[fb10_01]],["dsc"]=[[何员外修的何园是扬州城中数一数二的好园林，就是传到江南也颇有些名声，园内假山水池错落有致，一草一木，别具匠心，往往细微之处却又有曲径通幽之感。满目芳华，扑鼻芬香，令人陶醉。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_02]],["item1"]=[[21zstrigger01]],["name"]=[[何园]],["permission"]=2,["role1"]=[[fb10r02_1]],["role2"]=[[fb10r02_2]],["role3"]=[[jqbnpc_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_03]],["visible"]=1},["fb10_03"]={["down"]=[[fb10_02]],["dsc"]=[[这里街道比草河东岸的长街窄的多，也干净平整的多，行人稀少，河岸边上的杨柳、碧桃倒影河中，摇曳多姿，整条街显的极为幽静。街边少有店铺酒楼，大多门户紧闭，两边伺立着一对石狮，看来这一带住的大多是官宦缙绅人家。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_03]],["name"]=[[草河南街]],["permission"]=2,["right"]=[[fb10_04]],["role1"]=[[fb10r03_1]],["role2"]=[[fb10r03_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_04"]={["dsc"]=[[太平桥极为别致，桥对称二主拱，主拱间一小圆拱，两边各一肩拱，富于不同一般的韵律。太平桥两侧围石栏板，间以望柱，中间镶石额「太平桥」。太平桥横卧于官河之上，远望之如美人的两弯柳眉，明月当空时，两拱之下各一月影，如美人之妙目顾盼流转，为扬州一奇景。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_04]],["item1"]=[[fb10item6]],["left"]=[[fb10_03]],["name"]=[[太平桥]],["permission"]=2,["right"]=[[fb10_05]],["role1"]=[[fb10r04_1]],["role2"]=[[fb10r04_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_05"]={["down"]=[[fb10_53]],["dsc"]=[[南门大街宽二十余丈，青砖铺地，东侧有一两丈宽、一丈深的排水沟，街的中心种着槐树隔开道路，行人分左右而行。西边是官河，也叫草河，岸边依次种着杨柳和碧桃、街西是太平桥，街东是城守署。由于城守署在此的缘故，行人大多匆匆而过。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_05]],["item1"]=[[fubentiaozhuan6]],["left"]=[[fb10_04]],["name"]=[[南门大街]],["permission"]=2,["right"]=[[fb10_06]],["role1"]=[[fb10r05_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_10]],["visible"]=1},["fb10_06"]={["down"]=[[fb10_62]],["dsc"]=[[禾嘉街南面是城守署，几个士兵在站岗，不时有士兵校尉进出。行人到此，多不敢停留，怕惹是非。街道宽敞整洁，也少有泼皮在此打闹。北面多为民宅，屋檐比次密接。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_06]],["left"]=[[fb10_05]],["name"]=[[禾嘉街]],["permission"]=2,["right"]=[[fb10_07]],["role1"]=[[fb10r06_2]],["role2"]=[[fb10r06_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_08]],["visible"]=1},["fb10_07"]={["dsc"]=[[小东门桥由青石筑成，桥面光滑平整，据说是前朝所建，年代久远。河中心的桥墩上爬满了青苔，青青的河水从桥下悠然流过，滋润着青苔，孕育了扬州。你站在桥上，看着小秦淮河两边的密密的屋檐，听着偶尔传出的儿童的嬉笑声，你感受到扬州悠闲的一面。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_07]],["item1"]=[[fb10item4]],["left"]=[[fb10_06]],["name"]=[[小桥东门]],["permission"]=2,["role1"]=[[fb10r07_1]],["role2"]=[[fb10r07_2]],["role3"]=[[fb10r07_3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_08"]={["down"]=[[fb10_06]],["dsc"]=[[在园之东北隅，叠山石一撮，植花木少许。在园之西侧，贴墙筑半廊，与半亭连续。于园之西南，横断园林，造客斋一间。斋之南，留有隙地，到也小有天地。整个园地，纵深约三十步，宽仅十步许。身步不移，全园景物，即可全收眼底。北向有堂屋一间。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_08]],["name"]=[[容膝园]],["permission"]=2,["role1"]=[[fb10r08_1]],["role2"]=[[fb10r08_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_11]],["visible"]=1},["fb10_09"]={["dsc"]=[[你一走进来，就闻到一股茶香沁入心脾，精神为之一爽。几张八仙桌一字排开，坐满了客人，或高声谈笑，或交头接耳。你要想打听江湖掌故和谣言，这里是个好所在。]],["enterable"]=1,["id"]=[[fb10_09]],["item1"]=[[QX6r09_1]],["name"]=[[春来茶馆]],["permission"]=2,["right"]=[[fb10_10]],["role1"]=[[fb10r09_2]],["role2"]=[[fb10r09_3]],["role3"]=[[fb10r09_4]],["role4"]=[[fb10r09_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_10"]={["down"]=[[fb10_05]],["dsc"]=[[这里就是张佑诗中写的「十里长街市井连，月明桥上望神仙」的十里长街。长街宽达三十丈，青砖铺地，东边一道泄水沟。西边是官河。北边通往市中心，西边是一家顾客众多的茶馆。东边一座两层的楼房传来阵阵浪笑，那就是天下闻名的丽春院。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_10]],["item1"]=[[jqbpd]],["item2"]=[[sy5chufa02]],["left"]=[[fb10_09]],["name"]=[[十里长街]],["permission"]=2,["right"]=[[fb10_11]],["role1"]=[[tsjiajunpc]],["role2"]=[[fb10r10_2]],["role3"]=[[fb10r10_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_13]],["visible"]=1},["fb10_11"]={["down"]=[[fb10_08]],["dsc"]=[[屋之南北饰一雕花窗栏隔扇，东西两山墙辟有大块窗格，四面空明。正中壁上笔悬一幅巨制梅桩中堂，笔力遒劲，墨气飞动，左右挂一楹联。倚墙设一套红木条几，上陈古瓶，盆景。几前一海梅雕花方桌，桌旁一对海梅雕花太师椅。设竹榻，榻旁一架古书，缥湘零乱。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb10_11]],["left"]=[[fb10_10]],["name"]=[[丽春院]],["permission"]=2,["role1"]=[[fb10r11_1]],["role2"]=[[fb10r11_2]],["role3"]=[[QX6r11_1]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_12"]={["dsc"]=[[这里是淮扬赌场的大院，烟花三月的扬州，怎么能少了这个？院子四周是通往各个房间的通道。隐隐可以听到传出来吆五喝六的声音。你摇头一笑，想要的正是这个调调儿。]],["enterable"]=1,["id"]=[[fb10_12]],["name"]=[[赌场]],["permission"]=2,["right"]=[[fb10_13]],["role1"]=[[fb10r12_1]],["role2"]=[[fb10r12_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_13"]={["down"]=[[fb10_10]],["dsc"]=[[十里长街原本是扬州的中心，繁华之至。街边茶肆酒楼林立，店铺面街开店，热闹非凡，每当夜市来临时，店家高挂灯笼，尽夜喧哗，灯火不绝。十里长街的繁荣教往昔已逊色许多，但做为进出扬州的要道，依旧行人拥挤，车马如流。北边是一个热闹的广场。东边是一家店铺。西边则是一片喧嚣，原来那是方圆千里之内最大的一家赌场。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_13]],["left"]=[[fb10_12]],["name"]=[[十里长街]],["permission"]=2,["right"]=[[fb10_14]],["role1"]=[[fb10r13_1]],["role2"]=[[fb10r13_2]],["role3"]=[[fb10r13_3]],["role4"]=[[dyr13_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_25]],["visible"]=1},["fb10_14"]={["BgmDown"]=1,["dsc"]=[[这是一家以买卖公平著称的当铺，一个五尺高的柜台挡在你的面前，柜台上摆着一个牌子，柜台后坐着唐老板，一双精明的上上下下打量着你。]],["enterable"]=1,["id"]=[[fb10_14]],["item1"]=[[fb10item27]],["item2"]=[[fb10item28]],["item3"]=[[fb10item29]],["left"]=[[fb10_13]],["name"]=[[当铺]],["permission"]=2,["role1"]=[[fb10r14_1]],["role2"]=[[fb10item24]],["role3"]=[[fb10item25]],["role4"]=[[fb10item26]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_15"]={["BgmDown"]=1,["dsc"]=[[扬州武馆是专为初出江湖的少年设立的。由于江湖叛师是十分为人不齿的，初出道的少年可以在此学习一些基本的防身武功，一来不会光阴虚度，二来也好为今后选定一个心慕的门派。]],["enterable"]=1,["id"]=[[fb10_15]],["name"]=[[扬州武馆]],["permission"]=2,["role1"]=[[fb10r15_1]],["role2"]=[[fb10r15_2]],["role3"]=[[fb10r15_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_20]],["visible"]=1},["fb10_16"]={["dsc"]=[[这里是兵营，密密麻麻到处都是官兵，有的在武将的指挥下列队操练，有的独自在练功，有的坐着、躺着正在休息。南墙下坐着主帅，不动声色地寻视着四周。看到你进来，他们全都向你包围了过来，形势看来不太妙。南边有一个门。]],["enterable"]=1,["id"]=[[fb10_16]],["item1"]=[[QX6item3]],["name"]=[[兵营]],["permission"]=2,["role1"]=[[fb10r16_3]],["role2"]=[[QXr16_1]],["role3"]=[[QXr16_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_21]],["visible"]=1},["fb10_17"]={["BgmDown"]=1,["dsc"]=[[这是一家小小的杂货铺，大箱小箱堆满了一地，都是一些日常用品。杨掌柜懒洋洋地躺在一只躺椅上，招呼着过往行人。据说私底下他也卖一些贵重的东西。摊上立着一块招牌。]],["enterable"]=1,["id"]=[[fb10_17]],["name"]=[[杂货铺]],["permission"]=1,["role1"]=[[fb10r17_1]],["role2"]=[[dgnpc1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_26]],["visible"]=1},["fb10_18"]={["BgmDown"]=1,["dsc"]=[[这是一家简陋的打铁铺，中心摆着一个火炉，炉火把四周照得一片通红，你一走进去就感到浑身火热。墙角堆满了已完工和未完工的菜刀、铁锤、铁棍、匕首、盔甲等物。一位铁匠满头大汗挥舞着铁锤，专心致志地在打铁。]],["enterable"]=1,["id"]=[[fb10_18]],["item1"]=[[duanzaoronglu1]],["name"]=[[打铁铺]],["permission"]=1,["role1"]=[[fb10r18_1]],["role2"]=[[tiejiangsr]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_27]],["visible"]=1},["fb10_19"]={["down"]=[[fb10_54]],["dsc"]=[[你走在通泗街上，感到这里的街面要比别处的干净、整洁。大概因为靠近衙门、兵营可受保护的缘故，富人们都喜欢住在这里。东边静悄悄地没有几个行人，西边是西城门通往郊外。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_19]],["item1"]=[[fb10item18]],["item2"]=[[wldhpd]],["item3"]=[[vote2item1]],["item4"]=[[vote3item1]],["left"]=[[fb10_56]],["name"]=[[通泗门]],["permission"]=2,["right"]=[[fb10_20]],["role1"]=[[fb10r19_1]],["role2"]=[[fb10r19_2]],["role3"]=[[fb10r19_3]],["role4"]=[[jiayuanyindao1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_30]],["visible"]=1},["fb10_20"]={["down"]=[[fb10_15]],["dsc"]=[[你走在通泗街上，感到这里的街面要比别处的干净、整洁。大概因为靠近衙门、兵营可受保护的缘故，富人们都喜欢住在这里。东边静悄悄地没有几个行人，西边是西城门通往郊外。南边是一座武馆，北边是一所富丽堂皇的大宅院。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_20]],["item1"]=[[fb10fyb]],["left"]=[[fb10_19]],["name"]=[[通泗街]],["permission"]=2,["right"]=[[fb10_21]],["role1"]=[[fb10r20_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_31]],["visible"]=1},["fb10_21"]={["down"]=[[fb10_16]],["dsc"]=[[这是一条宽阔的青石板街道，向东西两头延伸。西大街是衙门所在，行人稀少，静悄悄地很是冷清。东边是一个热闹的广场。南边是兵营。北边就是衙门了。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_21]],["item1"]=[[bfitem1]],["left"]=[[fb10_20]],["name"]=[[通泗街]],["permission"]=2,["right"]=[[fb10_22]],["role1"]=[[fb10r21_1]],["role2"]=[[znq3cd11]],["role3"]=[[znq3cd1a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_32]],["visible"]=1},["fb10_22"]={["down"]=[[fb10_41]],["dsc"]=[[通泗街由大块青石砌成，两边整齐的种着槐树，树下各有一道排水沟。北边是扬州官衙，门前立着一对石狮，门上挂一匾额「扬州」。行人到此多加快脚步，免惹是非，车马亦加上一鞭，加速通过。南面都是民宅，几条小巷曲折穿插其中，偶然有一顶轿子进出。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_22]],["left"]=[[fb10_21]],["name"]=[[通泗街]],["permission"]=2,["right"]=[[fb10_23]],["role1"]=[[fb10r22_1]],["role2"]=[[fb10r22_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_51]],["visible"]=1},["fb10_23"]={["down"]=[[fb10_60]],["dsc"]=[[沿小街西边是扬州官衙的高墙，多开漏窗，倚墙种着槐树，透过槐树、漏窗，依稀可看到墙内是个园子。东边是官河，杨柳、碧桃临河而植。小街向北边穿过小广场通向扬州的府学「资政书院」。东面是通泗桥，连接着官河对岸的十里长街。南边多为民宅。西面是通泗街。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_23]],["left"]=[[fb10_22]],["name"]=[[草河小街]],["permission"]=2,["right"]=[[fb10_24]],["role1"]=[[fb10r23_1]],["role2"]=[[fb10r23_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_24"]={["dsc"]=[[通泗街由大块青石砌成，两边整齐的种着槐树，树下各有一道排水沟。北边是扬州官衙，门前立着一对石狮，门上挂一匾额「扬州」。行人到此多加快脚步，免惹是非，车马亦加上一鞭，加速通过。南面都是民宅，几条小巷曲折穿插其中，偶然有一顶轿子进出。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_24]],["item1"]=[[fb10item5]],["left"]=[[fb10_23]],["name"]=[[通泗桥]],["permission"]=2,["right"]=[[fb10_25]],["role1"]=[[fb10r24_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_25"]={["down"]=[[fb10_13]],["dsc"]=[[这里是城市的正中心，一个很宽阔的广场，铺着青石地面。一些游手好闲的人在这里溜溜达达，经常有艺人在这里表演。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_25]],["item1"]=[[bfitem2]],["left"]=[[fb10_24]],["leftUp"]=[[fb10_59]],["name"]=[[中央广场]],["permission"]=1,["right"]=[[fb10_26]],["role1"]=[[fb10r25_1]],["role2"]=[[fb10r25_2]],["role3"]=[[fb10r25_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_35]],["visible"]=1},["fb10_26"]={["down"]=[[fb10_17]],["dsc"]=[[这是一条宽阔的青石板街道，向东西两头延伸。东边不时地传来金属撞击声，西边人声嘈杂。北边是一座简朴的院子，半月形的大门上方写着“白鹿书院”四个烫金大字，苍劲有力。里面不时地传来学生们抑扬顿挫的读书声。南边是一家杂货铺。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_26]],["item1"]=[[fb10item20]],["left"]=[[fb10_25]],["name"]=[[甘泉街]],["permission"]=1,["right"]=[[fb10_27]],["role1"]=[[fb10r26_1]],["role2"]=[[fb10r26_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_33]],["visible"]=1},["fb10_27"]={["down"]=[[fb10_18]],["dsc"]=[[你走在东大街上，踩着坚实的青石板地面。东边是东城门，可以听到守城官兵的吆喝声，与西边朗朗的读书声混杂在一起。北边是一家老字号的药铺，南边是打铁铺，叮叮当当的声音老远就能听到。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_27]],["left"]=[[fb10_26]],["name"]=[[甘泉街]],["permission"]=1,["right"]=[[fb10_28]],["role1"]=[[ever27_1]],["role2"]=[[fb10r10_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_34]],["visible"]=1},["fb10_28"]={["down"]=[[fb10_55]],["dsc"]=[[甘泉街原本是扬州最繁华的街道之一，由于小秦淮河东岸的扬州新城的扩建，商家多搬去新城了，甘泉街才冷清许多，也干净许多。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_28]],["item1"]=[[fubentiaozhuan7]],["left"]=[[fb10_27]],["name"]=[[甘泉街]],["permission"]=1,["right"]=[[fb10_29]],["role1"]=[[fb10r28_1]],["role2"]=[[dwnpc39]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_58]],["visible"]=1},["fb10_29"]={["dsc"]=[[宁海桥是一座新建的联拱石桥，座落在小秦淮河上，是连接扬州新旧两城的要道，因此修的极为宽阔平整，可供四辆马车同时并行。桥名由欧阳修亲笔题写，悬在桥的两侧。桥的东南边有一个码头，许多船只停靠着。西边是扬州旧城的甘泉街。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_29]],["item1"]=[[fb10item12]],["item2"]=[[QX6item2]],["item3"]=[[cg2item1]],["left"]=[[fb10_28]],["name"]=[[宁海桥]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_30"]={["down"]=[[fb10_19]],["dsc"]=[[这是一片烂漫的桃花林，满山遍野的桃树枝上，开着桃红的桃花。桃花上头，飞满了细细嗡嗡的不甘寂寞的蜜蜂。脚下是一条不宽也不窄的林间小道，道边是密密丛丛的嫩草和争奇斗艳的小花。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb10_30]],["item1"]=[[fb10r30_5]],["item2"]=[[fb10r30_6]],["name"]=[[桃花谷]],["permission"]=2,["role1"]=[[fb10r30_1]],["role2"]=[[fb10r30_2]],["role3"]=[[fb10r30_3]],["role4"]=[[fb10r30_4]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_31"]={["BgmDown"]=1,["down"]=[[fb10_20]],["dsc"]=[[一座富丽堂皇的大宅院出现在你的眼前，两头高大的石狮子镇住了大门两侧，朱漆大门足足有三寸厚。门上挂着两个灯笼，写着“崔”字。崔家是当地首富，而且以蛮横著称。几条狼狗嚎叫着向你冲了过来。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb10_31]],["name"]=[[财主家]],["permission"]=2,["role1"]=[[fb10r31_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_40]],["visible"]=1},["fb10_32"]={["BgmDown"]=1,["down"]=[[fb10_21]],["dsc"]=[[这里是衙门大门，两扇朱木大门紧紧关闭着。“肃静”“回避”的牌子分放两头石狮子的旁边。前面有一个大鼓，显然是供小民鸣冤用的。几名衙役在门前巡逻。]],["enterable"]=1,["id"]=[[fb10_32]],["name"]=[[衙门]],["permission"]=2,["role1"]=[[fb10r32_2]],["role2"]=[[fb10r32_3]],["role3"]=[[yangzhou003]],["role4"]=[[jqbnpc2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_33"]={["BgmDown"]=1,["down"]=[[fb10_26]],["dsc"]=[[这里是书院的讲堂，窗明几净，一尘不染。一位庄重严肃的老者坐在太师椅上讲学，那就是当今大儒吴先生了。在他的两侧坐满了求学的学生。一张古意盎然的书案放在吴先生的前面，案上摆着几本翻开了的线装书籍。值得一提的是嵌在讲堂前左壁的学规。书院老夫子刚奉了圣旨颁发学位，就在门口树着书院新立的学位公告板。]],["enterable"]=1,["id"]=[[fb10_33]],["item1"]=[[guanjianpc]],["item2"]=[[fb10item1000]],["name"]=[[书院]],["permission"]=1,["role1"]=[[fb10r33_1]],["role2"]=[[fb10r33_2]],["role3"]=[[fb10r33_3]],["role4"]=[[fb10r33_4]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_34"]={["BgmDown"]=1,["down"]=[[fb10_27]],["dsc"]=[[这是一家药铺，一股浓浓的药味让你几欲窒息，那是从药柜上的几百个小抽屉里散发出来的。神医平老怪坐在茶几旁，独自喝着茶，看也不看你一眼。一名小伙计站在柜台后招呼着顾客。柜台上贴着一张发黄的广告。]],["enterable"]=1,["id"]=[[fb10_34]],["item1"]=[[lylitem1]],["name"]=[[药铺]],["permission"]=1,["role1"]=[[fb10r34_2]],["role2"]=[[fb10r34_4]],["role3"]=[[fb10r34_5]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_35"]={["down"]=[[fb10_25]],["dsc"]=[[这是一条宽阔的青石街道，向南北两头延伸。北边是北城门通向城外。南边显得很繁忙。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_35]],["name"]=[[十里长街]],["permission"]=2,["role1"]=[[fb10r35_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_36]],["visible"]=1},["fb10_36"]={["down"]=[[fb10_35]],["dsc"]=[[这是一条宽阔的青石街道，向南北两头延伸。北边是北城门通向城外。南边显得很繁忙。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_36]],["name"]=[[十里长街]],["permission"]=2,["role1"]=[[fb10r36_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_37]],["visible"]=1},["fb10_37"]={["down"]=[[fb10_36]],["dsc"]=[[北门街宽约二十丈，中间以槐树隔开，行人分行左右。街边有排水沟直接通向官河。街西是大虹桥，街东通向琼花街。北边是扬州的北门「镇淮门」。街东边是名扬天下的崇雅书院，隐隐可以听到朗朗的读书声。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_37]],["item1"]=[[fubentiaozhuan5]],["name"]=[[北门大街]],["permission"]=2,["right"]=[[fb10_38]],["role1"]=[[fb10r37_1]],["role2"]=[[fb10r37_2]],["role3"]=[[fb10r37_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_52]],["visible"]=1},["fb10_38"]={["dsc"]=[[琼花街虽是青石铺地，地面却多有裂缝，也不平整，大概琼花街是条老街的缘故。两边的屋檐密密重重，傍河而建，数条小巷穿插其中。行人大多匆匆而过，偶然有马蹄磕击青石的“哒哒”声。北面就是崇雅书院，朱先生在此传授学问。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_38]],["item1"]=[[QXr38_1]],["left"]=[[fb10_37]],["name"]=[[琼花街]],["permission"]=2,["right"]=[[fb10_39]],["role1"]=[[fb10r38_1]],["role2"]=[[fb10r38_2]],["role3"]=[[fb10r38_3]],["role4"]=[[zuimengsheng]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_39"]={["dsc"]=[[拾级而上，步上开明桥头。桥两侧围以石栏，每块石栏板雕刻着四时花木，雕刻精致，神形俱美。正处河心的石栏镶着一匾额「开明桥」。开明桥据说是扬州城里最古老的桥，能在五代战火之中幸存下来，扬州的老人对开明桥多有感慨。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb10_39]],["item1"]=[[fb10item3]],["left"]=[[fb10_38]],["name"]=[[开明桥]],["permission"]=2,["role1"]=[[fb10r39_1]],["role2"]=[[fb10r39_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb10_40"]={["down"]=[[fb10_31]],["dsc"]=[[这是一个小小的柴房，十分脏乱。]],["id"]=[[fb10_40]],["item1"]=[[fb10item19]],["name"]=[[柴房]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb10_41"]={["dsc"]=[[这是扬州城的驿站，驿差们进进出出，给各地送去信件。]],["id"]=[[fb10_41]],["item1"]=[[fb10item30]],["name"]=[[驿站]],["permission"]=2,["role1"]=[[fb10r41_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_22]]},["fb10_42"]={["dsc"]=[[这里是应试者单独待的房间，每间隔开，小小一格，放着书桌椅子，已铺好笔墨。]],["id"]=[[fb10_42]],["item1"]=[[fb10item32]],["name"]=[[号房]],["permission"]=2,["right"]=[[fb10_43]],["stepMusic"]=[[jiaobu]]},["fb10_43"]={["down"]=[[fb10_46]],["dsc"]=[[省试在尚书院举行，大殿比乡试贡院气派不少。贡院门口有监考官严格检查应试者携带之物，大殿之内，应考者均不准大声喧哗，每人被单独分到号房之内。监考官来回巡视，气氛庄重肃穆。]],["id"]=[[fb10_43]],["left"]=[[fb10_42]],["name"]=[[省试贡院]],["permission"]=2,["right"]=[[fb10_44]],["stepMusic"]=[[jiaobu]]},["fb10_44"]={["dsc"]=[[这里是应试者单独待的房间，每间隔开，小小一格，放着书桌椅子，已铺好笔墨。]],["id"]=[[fb10_44]],["left"]=[[fb10_43]],["name"]=[[号房]],["permission"]=2,["role1"]=[[kaosheng1]],["role2"]=[[fb10item33]],["stepMusic"]=[[jiaobu]]},["fb10_45"]={["dsc"]=[[这里是应试者单独待的房间，每间隔开，小小