},["fb10_54"]={["id"]=[[fb10_54]],["name"]=[[扬州西大街]],["permission"]=2,["role1"]=[[fubentiaozhuan3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_19]]},["fb10_55"]={["id"]=[[fb10_55]],["name"]=[[扬州东大街]],["permission"]=2,["role1"]=[[fubentiaozhuan4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_19]]},["fb10_56"]={["dsc"]=[[通泗门是扬州的西门，青砖砌成。城门前沿着城墙，在护城河边种着扬柳，因而扬州被称为「绿柳城郭」。几个士兵站在城门口，检查着过往行人车辆。这里是罪犯逃往西域的必经之地，官兵们戒备森严。城墙上贴着几张通缉告示。东边是城里。往北是一片桃林。]],["id"]=[[fb10_56]],["name"]=[[通泗门]],["permission"]=2,["right"]=[[fb10_19]],["stepMusic"]=[[jiaobu]]},["fb10_58"]={["down"]=[[fb10_28]],["dsc"]=[[扬州城中新开张的一家酒楼，楼内陈设富丽堂皇，桌椅等大多为贵重木材制成。松鹤楼大厨都是掌柜重金从各地请来的名厨，所做菜肴色香味均属上乘，但价格也高的吓人，因此是大多数富贵之人的好去处。]],["id"]=[[fb10_58]],["name"]=[[松鹤楼]],["permission"]=2,["role1"]=[[ss10_01]],["role2"]=[[20bafangshangren1]],["stepMusic"]=[[jiaobu]]},["fb10_59"]={["dsc"]=[[这是登月楼入口，西北方便是官河，杨柳、碧桃临河而植。东南方便是扬州的正中心，一个很宽阔的广场，铺着青石地面，有着不少行人在街上溜达。]],["id"]=[[fb10_59]],["name"]=[[登月楼]],["permission"]=2,["rightDown"]=[[fb10_25]],["role1"]=[[tlnpc]],["role2"]=[[tlnpc1]],["role3"]=[[tlnpc2]],["role4"]=[[tlnpc3]],["role5"]=[[tlnpc3a]],["stepMusic"]=[[jiaobu]]},["fb10_60"]={["down"]=[[fb10_61]],["dsc"]=[[一条偏僻巷子，两边耸立着一些怪石，奇形怪状，甚是有趣。]],["id"]=[[fb10_60]],["name"]=[[巷子]],["permission"]=2,["role1"]=[[fb10_114a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_23]]},["fb10_61"]={["dsc"]=[[宽阔平整，一尘不染。]],["id"]=[[fb10_61]],["item1"]=[[fubentiaozhuan8]],["name"]=[[街道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb10_60]]},["fb10_62"]={["dsc"]=[[无昼楼气势恢宏，飞檐插云如在仙境。楼内共三层，第一层摆设大大小小桌椅数十张，雅间古朴。第二层有侍从看守，酒色财气一应俱全，来这里的若非家财万贯、位高权重，那必定是在江湖中大有名气。第三层则非名宿不可进入，内设金碧辉煌，非常人可以想象。]],["id"]=[[fb10_62]],["name"]=[[无昼楼]],["permission"]=2,["role1"]=[[lpknpc1]],["role2"]=[[lpknpc9]],["role3"]=[[znqlr]],["role4"]=[[znqlr3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb10_06]]}}00000000